css:
.dcx,.dcx{margin:0;padding:0;background:#FAF8F3;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#0E3B2B;-webkit-font-smoothing:antialiased}
.dcx a{color:#0E3B2B;text-decoration:none}
.dcx a:hover{color:#0E8A52}
.dcx [data-z] div,.dcx [data-z] span,.dcx [data-z] a,.dcx [data-h1]{white-space:nowrap}
.dcx [data-z] p,.dcx [data-z] p *,.dcx [data-z] h2,.dcx [data-z] h2 *,.dcx [data-z] [data-wrap],.dcx [data-z] [data-wrap] *{white-space:normal}
@media (max-width:1040px){.dcx [data-scroll]{overflow-x:auto;max-width:100%}
.dcx [data-c]{grid-template-columns:minmax(0,1fr)!important;justify-items:center;row-gap:20px}
.dcx [data-c]>*{max-width:100%}
.dcx [data-hero]{flex-direction:column;align-items:center;height:auto!important;padding-bottom:24px}
.dcx [data-nav]{display:none!important}
}
@media (min-width:601px){.dcx [data-hero] [data-h1]{font-size:32px!important;line-height:40px!important;letter-spacing:-.6px!important}}
@media (max-width:600px){.dcx [data-v]{zoom:.6}
.dcx [data-row]{flex-wrap:wrap}
.dcx [data-h1]{font-size:30px!important;line-height:34px!important}
}
@media (max-width:760px){.dcx [data-g6]{grid-template-columns:repeat(3,minmax(0,1fr))!important}
}
@media (max-width:420px){.dcx [data-g6]{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}
@media (max-width:480px){.dcx [data-g8]{grid-template-columns:repeat(4,minmax(0,1fr))!important}
}
.dcx [data-scroll]{overflow-y:hidden}

.dch-3d1ded89:hover{transform:translateY(-1px) !important;color:#FFFFFF !important}
.dch-df2ff70f:hover{transform:translateY(-2px) !important;color:#FFFFFF !important}
